// Vendored helper: long minified-style bundle containing base64-looking
// constants and \xNN escape runs that weak YARA encoded-payload heuristics
// historically flagged. In bundled context these are hardening notes.
const TABLE = 'AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8gISIjJCUmJygpKissLS4vMDEyMzQ1Njc4OTo7PD0+P0BBQkNERUZHSElKS0xNTk9QUVJTVFVWV1hZWltcXV5fYGFiY2RlZmdoaWprbG1ub3BxcnN0dXZ3eHl6';
const ESCAPES = '\x01\x02\x03\x04\x05\x06\x07\x08\x0b\x0c\x0e\x0f\x10\x11\x12\x13\x16\x17\x18\x1a\x1c\x1d\x1e\x1f\x7f\x80\x85\xa0​‌‍﻿';
function decode(table, input) {
  return input.replace(/[A-Za-z0-9+/=]/g, (ch) => String.fromCharCode(TABLE.indexOf(ch)));
}
module.exports = { decode, ESCAPES };
